// The question bank. Shared by the browser (to play) and the server (to grade).
// Every question has exactly one `answer` and four `wrong` options; the game
// shuffles all five when it shows the question.
//
// visual types:
//   flag  { code }            ISO 3166-1 alpha-2, rendered from flagcdn.com
//   wiki  { title, logo?, hide? }  lead image of an English Wikipedia article (or a "File:…"); logo: shown on white;
//                             hide: parts to blur, see hideParts in public/js/visuals.js
//   map   { lat, lon, zoom }  satellite map with a marker in the centre
//   country { iso }          country silhouette (ISO 3166-1 numeric), from world-atlas
//   element { symbol, number, mass, family }  periodic-table tile
//   sign  { id }              road sign drawn in SVG (public/js/signs.js)
//   code  { text }            code snippet

const flag = (code, answer, wrong) => ({
  id: `flag-${code}`,
  cat: 'flags',
  prompt: 'Which country flies this flag?',
  visual: { type: 'flag', code },
  answer,
  wrong,
  about: answer, // the country this question is about (see pickQuestions)
});

const capital = (code, country, answer, wrong) => ({
  id: `capital-${code}`,
  cat: 'capitals',
  prompt: `What is the capital of ${country}?`,
  visual: { type: 'flag', code },
  answer,
  wrong,
  about: country.replace(/^the /, ''),
});

const water = (slug, lat, lon, zoom, answer, wrong) => ({
  id: `sea-${slug}`,
  cat: 'seas',
  prompt: 'Which body of water is marked on the map?',
  visual: { type: 'map', lat, lon, zoom },
  answer,
  wrong,
});

const sign = (id, answer, wrong) => ({
  id: `sign-${id}`,
  cat: 'signs',
  prompt: 'What is this road sign called?',
  visual: { type: 'sign', id },
  answer,
  wrong,
});

// Israeli road signs: the official drawings (Israel Ministry of Transport, public domain via
// Wikimedia Commons), saved in public/signs/il/ under their official sign number.
// `npm run fetch-signs` downloads any that are missing, using the `commons` file name.
const ilSign = (num, answer, wrong) => ({
  id: `sign-il-${num}`,
  cat: 'signs',
  prompt: 'What does this Israeli road sign mean?',
  visual: { type: 'image', src: `/signs/il/${num}.svg`, alt: 'An Israeli road sign', commons: `Israel road sign ${num}.svg` },
  answer,
  wrong,
});

const wiki = (cat, prompt) => (slug, title, answer, wrong) => ({
  id: `${cat}-${slug}`,
  cat,
  prompt,
  visual: { type: 'wiki', title },
  answer,
  wrong,
});

const animal = wiki('animals', 'What animal is this?');
const car = wiki('cars', 'Which car is this?');
const landmark = wiki('landmarks', 'What is this landmark called?');

// The newer picture topics pin a specific image file ("File:…"), the one that was checked
// for not giving the answer away, instead of whatever lead image the article has today.
const painting = wiki('paintings', 'What is this painting called?');
const anatomy = wiki('body', 'What is this part of the body called?');
const famous = wiki('people', 'Who is this?');
const beauty = wiki('beauty', 'What is this beauty product called?');
const job = wiki('jobs', 'What job does this picture show?');
// Logos without the brand's name in them, shown on white instead of as a photo.
const logo = (slug, title, answer, wrong) => ({ ...wiki('logos', "Which brand's logo is this?")(slug, title, answer, wrong), visual: { type: 'wiki', title, logo: true } });
// `hide` blurs the parts of the picture with the name written on it (see hideParts in public/js/visuals.js).
const crest = (slug, title, answer, wrong, hide) => ({ ...wiki('clubs', "Which football club's crest is this?")(slug, title, answer, wrong), visual: { type: 'wiki', title, logo: true, ...(hide && { hide }) } });
const footballer = wiki('footballers', 'Which football player is this?');
const currency = (slug, title, answer, wrong, hide) => ({ ...wiki('currencies', 'Which currency is this?')(slug, title, answer, wrong), visual: { type: 'wiki', title, ...(hide && { hide }) } });

const dog = wiki('dogs', 'Which dog breed is this?');
const food = wiki('food', 'What dish is this?');
const instrument = wiki('music', 'What instrument is this?');

const country = (iso, answer, wrong) => ({
  id: `country-${iso}`,
  cat: 'countries',
  prompt: 'Which country has this shape?',
  visual: { type: 'country', iso },
  answer,
  wrong,
  about: answer,
});

const element = (symbol, number, mass, family, answer, wrong) => ({
  id: `element-${symbol.toLowerCase()}`,
  cat: 'elements',
  prompt: 'Which element is this?',
  visual: { type: 'element', symbol, number, mass, family },
  answer,
  wrong,
});

// Text-only questions: no picture, the question is shown on its own card.
const book = (cat) => (slug, prompt, answer, wrong) => ({
  id: `${cat}-${slug}`,
  cat,
  prompt,
  visual: { type: 'text' },
  answer,
  wrong,
});
const sapiens = book('sapiens');
const habits = book('habits');
const sayno = book('sayno');

// Questions with their own wording: with `photo` (an English Wikipedia article title) the
// article's lead image is shown above the question, otherwise it is text only.
// Pick photos that don't give the answer away (no captions, labels or maps naming it).
const ask = (cat) => (slug, prompt, answer, wrong, photo) => ({
  id: `${cat}-${slug}`,
  cat,
  prompt,
  visual: photo ? { type: 'wiki', title: photo } : { type: 'text' },
  answer,
  wrong,
  ownPrompt: true,
});
// Famous books: bestsellers published after 2000 with over 1.5 million Goodreads ratings,
// described by their plot (never the title's words), since their covers show the title.
const novel = ask('novels');
const history = ask('history');
const trivia = ask('trivia');
// "Not what you think": questions whose obvious answer is wrong.
const unexpected = ask('unexpected');

const code = (slug, text, answer, wrong) => ({
  id: `code-${slug}`,
  cat: 'code',
  prompt: 'Which programming language is this?',
  visual: { type: 'code', text },
  answer,
  wrong,
});

